<?php
function documentType(int $id):?int{if(!$id)return null;if(!q('SELECT id FROM document_types WHERE id=? AND active=1',[$id])->fetchColumn())throw new DomainException('نوع مدرک فعال انتخاب کنید.');return $id;}
function documentTypesView():void{demand('settings');layout('settings','انواع مدارک','نوع جدید اضافه کنید یا نوع قبلی را غیرفعال کنید؛ مدارک قبلی حفظ می‌شوند.');foreach([['id'=>0,'name'=>'','active'=>1],...q('SELECT * FROM document_types ORDER BY id')->fetchAll()] as $t){echo '<section class="panel form-panel">';formstart('document_type_save');hidden('id',$t['id']);field('name','نام نوع مدرک',$t['name'],'text','',true);check('active','فعال',(bool)$t['active']);formend($t['id']?'ذخیره نوع':'افزودن نوع','/');echo '</section>';}endLayout();}
function documentTypeSave(int $id,string $name,bool $active):void{global $db;if(!allowed('settings'))throw new DomainException('اجازه مدیریت نوع مدرک ندارید.');if(trim($name)===''||mb_strlen($name)>160)throw new DomainException('نام معتبر وارد کنید.');$db->beginTransaction();try{if($id){if(!q('SELECT id FROM document_types WHERE id=? FOR UPDATE',[$id])->fetchColumn())throw new DomainException('نوع پیدا نشد.');q('UPDATE document_types SET name=?,active=? WHERE id=?',[$name,(int)$active,$id]);}else{q('INSERT INTO document_types(name,active) VALUES(?,?)',[$name,(int)$active]);$id=(int)$db->lastInsertId();}audit('document_type_saved',$id);$db->commit();}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}}

function classifyDocument(int $id,int $type):void{
 global $db;if(!allowed('patients.edit'))throw new DomainException('اجازه تغییر مدرک ندارید.');$type=documentType($type);$db->beginTransaction();try{$doc=q('SELECT * FROM physio_patient_documents WHERE id=? FOR UPDATE',[$id])->fetch();if(!$doc||!patientAllowed($doc['pid']))throw new DomainException('به مدرک دسترسی ندارید.');q('UPDATE physio_patient_documents SET document_type_id=? WHERE id=?',[$type,$id]);q('INSERT INTO document_events(document_id,actor_id,old_type,new_type) VALUES(?,?,?,?)',[$id,user()['id'],$doc['document_type_id'],$type]);$db->commit();}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}}
function classifyDocumentView():void{demand('patients.edit');$id=(int)($_GET['id']??0);$d=q('SELECT * FROM physio_patient_documents WHERE id=?',[$id])->fetch();if(!$d||!patientAllowed($d['pid'])){http_response_code(403);return;}layout('patients','دسته‌بندی مدرک');formstart('document_classify');hidden('document_id',$id);selectfield('document_type_id','نوع مدرک',['0'=>'بدون دسته']+options('document_types','active=1'),$d['document_type_id']??0);formend('ثبت دسته','/patient?id='.$d['pid']);endLayout();}
